-- Institution directory, student verification, marketplace monetization, and housing escrow foundations.
-- University source: National Universities Commission official federal/state/private pages fetched 2026-06-16.
-- College source: NCCE Accredited Colleges page fetched 2026-06-16.
-- Polytechnic source: curated NBTE-regulated baseline; the official NBTE 25th Edition 2025 list is imported in 20260616230500_nbte_polytechnic_directory_2025.sql.

ALTER TABLE public.universities
  ADD COLUMN IF NOT EXISTS institution_type TEXT NOT NULL DEFAULT 'university' CHECK (institution_type IN ('university', 'polytechnic', 'college_of_education', 'monotechnic', 'other')),
  ADD COLUMN IF NOT EXISTS ownership TEXT CHECK (ownership IN ('Federal', 'State', 'Private', 'Military', 'Other')),
  ADD COLUMN IF NOT EXISTS state TEXT,
  ADD COLUMN IF NOT EXISTS region TEXT,
  ADD COLUMN IF NOT EXISTS city TEXT,
  ADD COLUMN IF NOT EXISTS website_url TEXT,
  ADD COLUMN IF NOT EXISTS accent_color TEXT NOT NULL DEFAULT '#2563eb',
  ADD COLUMN IF NOT EXISTS community_prompt TEXT,
  ADD COLUMN IF NOT EXISTS campus_motto TEXT,
  ADD COLUMN IF NOT EXISTS source_label TEXT;

ALTER TABLE public.profiles
  ADD COLUMN IF NOT EXISTS student_verification_status TEXT NOT NULL DEFAULT 'unverified' CHECK (student_verification_status IN ('unverified', 'pending', 'verified', 'rejected')),
  ADD COLUMN IF NOT EXISTS student_id_number TEXT,
  ADD COLUMN IF NOT EXISTS matric_number TEXT,
  ADD COLUMN IF NOT EXISTS verification_document_url TEXT,
  ADD COLUMN IF NOT EXISTS verification_notes TEXT,
  ADD COLUMN IF NOT EXISTS verified_at TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS agent_verification_status TEXT NOT NULL DEFAULT 'none' CHECK (agent_verification_status IN ('none', 'pending_payment', 'pending_review', 'verified', 'rejected')),
  ADD COLUMN IF NOT EXISTS agent_paid_at TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS agent_monthly_post_limit INTEGER NOT NULL DEFAULT 100,
  ADD COLUMN IF NOT EXISTS agent_daily_post_limit INTEGER NOT NULL DEFAULT 10;

ALTER TABLE public.marketplace_listings
  ADD COLUMN IF NOT EXISTS listing_plan TEXT NOT NULL DEFAULT 'commission' CHECK (listing_plan IN ('commission', 'upfront_fee', 'verified_agent')),
  ADD COLUMN IF NOT EXISTS commission_rate NUMERIC NOT NULL DEFAULT 0.10,
  ADD COLUMN IF NOT EXISTS platform_fee_amount NUMERIC NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS payment_status TEXT NOT NULL DEFAULT 'not_required' CHECK (payment_status IN ('not_required', 'pending', 'paid', 'failed', 'refunded')),
  ADD COLUMN IF NOT EXISTS target_scope TEXT NOT NULL DEFAULT 'local' CHECK (target_scope IN ('local', 'regional', 'nationwide')),
  ADD COLUMN IF NOT EXISTS admin_review_notes TEXT;

ALTER TABLE public.hostel_listings
  ADD COLUMN IF NOT EXISTS student_service_fee_rate NUMERIC NOT NULL DEFAULT 0.10,
  ADD COLUMN IF NOT EXISTS student_service_fee_amount NUMERIC NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS total_student_price NUMERIC,
  ADD COLUMN IF NOT EXISTS escrow_status TEXT NOT NULL DEFAULT 'not_started' CHECK (escrow_status IN ('not_started', 'pending_payment', 'paid_to_platform', 'released_to_agent', 'refunded')),
  ADD COLUMN IF NOT EXISTS admin_review_notes TEXT;

ALTER TABLE public.roommate_requests
  ADD COLUMN IF NOT EXISTS verification_required BOOLEAN NOT NULL DEFAULT true,
  ADD COLUMN IF NOT EXISTS admin_review_notes TEXT;

CREATE TABLE IF NOT EXISTS public.student_verification_requests (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  university_id UUID REFERENCES public.universities(id),
  matric_number TEXT,
  student_id_number TEXT,
  document_url TEXT,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'verified', 'rejected')),
  admin_notes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

ALTER TABLE public.student_verification_requests ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Users can view their student verification requests" ON public.student_verification_requests;
CREATE POLICY "Users can view their student verification requests" ON public.student_verification_requests FOR SELECT USING (auth.uid() = user_id OR public.has_role(auth.uid(), 'super_admin') OR public.has_role(auth.uid(), 'moderator') OR public.has_role(auth.uid(), 'sub_admin'));
DROP POLICY IF EXISTS "Users can create their student verification requests" ON public.student_verification_requests;
CREATE POLICY "Users can create their student verification requests" ON public.student_verification_requests FOR INSERT WITH CHECK (auth.uid() = user_id);
DROP POLICY IF EXISTS "Admins can update student verification requests" ON public.student_verification_requests;
CREATE POLICY "Admins can update student verification requests" ON public.student_verification_requests FOR UPDATE USING (public.has_role(auth.uid(), 'super_admin') OR public.has_role(auth.uid(), 'moderator') OR public.has_role(auth.uid(), 'sub_admin'));
DROP TRIGGER IF EXISTS update_student_verification_requests_updated_at ON public.student_verification_requests;
CREATE TRIGGER update_student_verification_requests_updated_at BEFORE UPDATE ON public.student_verification_requests FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

CREATE TABLE IF NOT EXISTS public.agent_verification_requests (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  university_id UUID REFERENCES public.universities(id),
  legal_name TEXT NOT NULL,
  phone_number TEXT NOT NULL,
  business_name TEXT,
  identity_document_url TEXT,
  payment_id UUID REFERENCES public.payments(id),
  fee_amount NUMERIC NOT NULL DEFAULT 20000,
  status TEXT NOT NULL DEFAULT 'pending_payment' CHECK (status IN ('pending_payment', 'pending_review', 'verified', 'rejected')),
  admin_notes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

ALTER TABLE public.agent_verification_requests ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Users can view their agent verification requests" ON public.agent_verification_requests;
CREATE POLICY "Users can view their agent verification requests" ON public.agent_verification_requests FOR SELECT USING (auth.uid() = user_id OR public.has_role(auth.uid(), 'super_admin') OR public.has_role(auth.uid(), 'moderator'));
DROP POLICY IF EXISTS "Users can create their agent verification requests" ON public.agent_verification_requests;
CREATE POLICY "Users can create their agent verification requests" ON public.agent_verification_requests FOR INSERT WITH CHECK (auth.uid() = user_id);
DROP POLICY IF EXISTS "Admins can update agent verification requests" ON public.agent_verification_requests;
CREATE POLICY "Admins can update agent verification requests" ON public.agent_verification_requests FOR UPDATE USING (public.has_role(auth.uid(), 'super_admin') OR public.has_role(auth.uid(), 'moderator'));
DROP TRIGGER IF EXISTS update_agent_verification_requests_updated_at ON public.agent_verification_requests;
CREATE TRIGGER update_agent_verification_requests_updated_at BEFORE UPDATE ON public.agent_verification_requests FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name,
  location = EXCLUDED.location,
  website_url = COALESCE(EXCLUDED.website_url, public.universities.website_url),
  institution_type = EXCLUDED.institution_type,
  ownership = EXCLUDED.ownership,
  state = EXCLUDED.state,
  region = EXCLUDED.region,
  accent_color = EXCLUDED.accent_color,
  community_prompt = EXCLUDED.community_prompt,
  campus_motto = EXCLUDED.campus_motto,
  source_label = EXCLUDED.source_label,
  updated_at = now();
